export class Context {
    /**
     * Initializes the context.
     *
     * @returns {Promise<this>} The context instance as Promise
     */
    async init() {
        if (this.isInitialized) {
            return this;
        }
        await Promise.resolve();
        this.isInitialized = true;
        return this;
    }
    name() {
        return 'context';
    }
}
